x = Symbol('x')

def nolim_at(N, D, a):
    """N/D 의 x->a 극한이 (유한값으로) 존재하지 않으면 True"""
    Np, Dp = Poly(expand(N), x), Poly(expand(D), x)
    if Dp.is_zero:
        return True
    G = gcd(Np, Dp)
    D1 = quo(Dp, G)
    return D1.eval(a) == 0

def all_ok(N, D):
    """모든 실수 a 에서 극한이 존재하면 True"""
    Np, Dp = Poly(expand(N), x), Poly(expand(D), x)
    G = gcd(Np, Dp)
    D1 = quo(Dp, G)
    return D1.count_roots() == 0

def cand():
    vals = set()
    for m in [Rational(k, 2) for k in range(-12, 13) if k != 0]:
        for n in [Rational(k, 2) for k in range(-30, 31)]:
            N = m*(x + 1) + n
            D = (x - 2)*(m*x + n - 4)
            if not nolim_at(N, D, 2) and nolim_at(N, D, 5):
                vals.add(m*10 + n)
    return vals

def skill():
    m, n = symbols('m n')
    s = solve([3*m + n, 5*m + n - 4], [m, n])
    return s[m]*10 + s[n]

def standard():
    v = cand()
    assert len(v) == 1
    return list(v)[0]

def unique():
    return sorted(cand())
